    "directionalLightToggle": { "type": "Toggle", "props": { "value": { "$bindState": "/visibility/Directional Light" } } },
    
    "environment": { "type": "ListItem", "props": { "label": "Environment", "style": { "paddingLeft": "20px" } }, "children": ["environmentIcon", "environmentToggle"] },
