    "skyDomeToggle": { "type": "Toggle", "props": { "value": { "$bindState": "/visibility/Sky Dome" } } },
    
    "characters": { "type": "ListItem", "props": { "label": "Characters", "style": { "paddingLeft": "20px" } }, "children": ["charactersIcon", "charactersToggle"] },
    "charactersIcon": { "type": "Icon", "props": { "name": "users" } },
    "charactersToggle": { "type": "Toggle", "props": { "value": { "$bindState": "/visibility/Characters" } } },
    
    "playerModel": { "type": "ListItem", "props": { "label": "Player Model", "style": { "paddingLeft": "40px", "backgroundColor": { "$state": "/selectedObject" } === "Player Model" ? "#e3f2fd" : "transparent" } }, "children": ["playerBadge", "playerModelToggle"] },
