    "npcGuard": { "type": "ListItem", "props": { "label": "NPC Guard", "style": { "paddingLeft": "40px" } }, "children": ["npcGuardToggle"] },
    "npcGuardToggle": { "type": "Toggle", "props": { "value": { "$bindState": "/visibility/NPC Guard" } } },
    
