    "props": { "type": "ListItem", "props": { "label": "Props", "style": { "paddingLeft": "20px" } }, "children": ["propsIcon", "propsToggle"] },
    "propsIcon": { "type": "Icon", "props": { "name": "box" } },
    "propsToggle": { "type": "Toggle", "props": { "value": { "$bindState": "/visibility/Props" } } },
    
    "treasureChest": { "type": "ListItem", "props": { "label": "Treasure Chest", "style": { "paddingLeft": "40px" } }, "children": ["treasureChestToggle"] },
