    "translateBtn": { "type": "Button", "props": { "label": "Translate", "variant": { "$state": "/viewport/activeTool" } === "Translate" ? "primary" : "secondary" }, "on": { "press": { "action": "setState", "path": "/viewport/activeTool", "value": "Translate" } } },
    "rotateBtn": { "type": "Button", "props": { "label": "Rotate", "variant": { "$state": "/viewport/activeTool" } === "Rotate" ? "primary" : "secondary" }, "on": { "press": { "action": "setState", "path": "/viewport/activeTool", "value": "Rotate" } } },
    "scaleBtn": { "type": "Button", "props": { "label": "Scale", "variant": { "$state": "/viewport/activeTool" } === "Scale" ? "primary" : "secondary" }, "on": { "press": { "action": "setState", "path": "/viewport/activeTool", "value": "Scale" } } },
    "toolDivider": { "type": "Divider", "props": { "orientation": "vertical" } },
